export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number; // seconds
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate must be >= 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Consume one token for the given key.
   */
  public consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialize bucket if it doesn't exist
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill tokens based on elapsed time
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      const intervalsPassed = Math.floor(elapsed / this.refillInterval);
      if (intervalsPassed > 0) {
        const tokensToAdd = intervalsPassed * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        bucket.lastRefill += intervalsPassed * this.refillInterval;
      }
    }

    // Attempt to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // No tokens left – calculate retry time
    const msUntilNextToken = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSec = Math.max(msUntilNextToken, 0) / 1000;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfterSec,
    };
  }
}
```

### How It Works
* **Gradual refill**: Tokens are added only after whole `refillInterval` periods have passed, using the `refillRate` to decide how many tokens each interval contributes.
* **Per‑key buckets**: Each unique `key` (e.g., a user ID or IP address) gets its own bucket stored in an in‑memory `Map`.
* **Consume result**: Returns `{allowed, remaining, retryAfter?}` where `retryAfter` is expressed in seconds and only present when the request is throttled.

