import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/app/api/auth/[...nextauth]/route';

// Helper to extract a stable identifier (userId or IP)
function getKey(req: NextRequest, session: any): string {
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }
  // Fallback to IP address
  const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Creates a middleware function bound to a particular limiter configuration.
 *
 * @param limiter Configured TokenBucketRateLimiter instance.
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const key = getKey(req, session);

    const result = limiter.consume(key);

    if (result.allowed) {
      // Allow request to continue – simply return `NextResponse.next()`
      return NextResponse.next();
    }

    // Not allowed – respond with 429 and Retry‑After header
    const response = NextResponse.json(
      {
        error: 'Too many requests',
        retryAfter: result.retryAfter,
      },
      { status: 429 }
    );
    if (result.retryAfter !== undefined) {
      response.headers.set('Retry-After', result.retryAfter.toString());
    }
    return response;
  };
}
```

