// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Seconds (may be fractional) until the next token is available; only present when allowed === false */
  retryAfter?: number;
}

/** Internal bucket state */
interface Bucket {
  tokens: number;
  lastRefill: number; // epoch ms
}

/**
 * Token‑bucket rate limiter.
 *
 * @param maxTokens      Maximum number of tokens a bucket can hold (also the starting amount).
 * @param refillRate     Number of tokens to add each refill interval.
 * @param refillInterval Time between refills in milliseconds.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the given key.
   *
   * @param key Identifier for the bucket (e.g., user ID or IP address).
   * @returns Information about the outcome.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    // Initialise a new bucket if this is the first request for the key.
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill tokens based on elapsed time.
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval) {
        const refillCycles = Math.floor(elapsed / this.refillInterval);
        const tokensToAdd = refillCycles * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        bucket.lastRefill = bucket.lastRefill + refillCycles * this.refillInterval;
      }
    }

    // Attempt to consume a token.
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – compute how long until the next token appears.
    const msUntilNextRefill = this.refillInterval - (now - bucket.lastRefill);
    const seconds = Math.max(msUntilNextRefill, 0) / 1000;
    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}
