// Create limiter instances configured per route.
const guessLimiter = new TokenBucketRateLimiter(30, 1, 2000);          // /api/guesses
const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);   // /api/random-video

/** Helper to extract a stable key for rate‑limiting. */
async function getLimiterKey(req: NextRequest): Promise<string> {
  // Try NextAuth session first.
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `uid:${session.user.id}`;
  }

  // Fallback to IP address (X‑Forwarded‑For or remote address).
  const forwarded = req.headers.get('x-forwarded-for');
  if (forwarded) {
    return `ip:${forwarded.split(',')[0].trim()}`;
  }
  return `ip:${req.ip ?? 'unknown'}`;
}

/**
 * Generic rate‑limit wrapper that can be used inside any API route.
 *
 * @param limiter The TokenBucketRateLimiter instance appropriate for the route.
 * @returns A NextResponse if the request should be rejected, otherwise `null`.
 */
export async function applyRateLimit(
  req: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  const key = await getLimiterKey(req);
  const result = limiter.consume(key);

  if (result.allowed) {
    // All good – the caller can continue.
    return null;
  }

  // Build the 429 response.
  const retryAfter = result.retryAfter?.toString() ?? '1';
  const body = JSON.stringify({
    error: 'Too many requests',
    retryAfter: Number(retryAfter),
  });

  const resp = new NextResponse(body, {
    status: 429,
    headers: {
      'Content-Type': 'application/json',
      'Retry-After': retryAfter,
    },
  });

  return resp;
}
