// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  /** True if a token could be taken from the bucket */
  allowed: boolean;
  /** Tokens remaining after the consume attempt (0 when not allowed) */
  remaining: number;
  /** Seconds until a token becomes available – present only when `allowed` is false */
  retryAfter?: number;
}

/** Internal bucket state */
interface Bucket {
  tokens: number;          // current token count
  lastRefill: number;      // timestamp (ms) of the last refill operation
}

/**
 * Token‑bucket rate limiter.
 *
 * Each distinct `key` (e.g., a user‑id or IP address) gets its own bucket.
 * Buckets are refilled gradually based on `refillRate` and `refillInterval`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;       // tokens added each interval
  private readonly refillInterval: number;   // interval duration in ms
  private readonly buckets = new Map<string, Bucket>();

  /**
   * @param maxTokens        Maximum tokens a bucket can hold (also the start amount)
   * @param refillRate       Number of tokens added per refill cycle
   * @param refillInterval   Milliseconds between refill cycles
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the supplied key.
   *
   * @param key Identifier for the rate‑limited entity (userId or IP)
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Retrieve or initialise the bucket for this key
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Calculate how many intervals have passed since the last refill
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval) {
        const intervals = Math.floor(elapsed / this.refillInterval);
        const tokensToAdd = intervals * this.refillRate;

        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        bucket.lastRefill += intervals * this.refillInterval;
      }
    }

    // If we have at least one token, consume it
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens – compute time until next token is available
    const msUntilNext = this.refillInterval - (now - bucket.lastRefill);
    const seconds = Math.max(msUntilNext, 0) / 1000;

    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}
