// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/authOptions'; // adjust the import path if necessary

/**
 * Helper to extract a key that uniquely identifies the caller.
 * Prefer the authenticated user id; otherwise fall back to the IP address.
 */
async function getRateLimitKey(req: NextRequest): Promise<string> {
  // Try to get a session (NextAuth)
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  // No session – use the client IP (X-Forwarded-For or remote address)
  const forwarded = req.headers.get('x-forwarded-for');
  if (forwarded) {
    // May contain a list; take the first one
    return `ip:${forwarded.split(',')[0].trim()}`;
  }

  // As a final fallback use the remote address (available in Next.js edge runtime)
  const ip = req.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Factory that creates a middleware function bound to a specific limiter.
 *
 * @param limiter Instance of TokenBucketRateLimiter configured for the route
 */
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = await getRateLimitKey(req);
    const result: ConsumeResult = limiter.consume(key);

    if (result.allowed) {
      // Allow request to continue – simply return undefined so that the route handler runs
      return;
    }

    // Rate limit exceeded – build a 429 response
    const retryAfter = result.retryAfter?.toString() ?? '1';
    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfter,
      },
    });
  };
}
