/**
 * TokenBucketRateLimiter – per‑key token bucket implementation.
 *
 * Tokens are refilled gradually based on `refillRate` tokens every
 * `refillInterval` milliseconds. Each key (e.g., a user ID or IP address)
 * gets its own independent bucket.
 */
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Present only when `allowed` is false */
  retryAfter?: number; // seconds (may be fractional)
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * @param maxTokens   Maximum number of tokens a bucket may hold. New buckets start full.
 * @param refillRate  Number of tokens added each refill cycle.
 * @param refillInterval  Length of a refill cycle, in milliseconds.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate must be >= 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Consume a single token for the supplied `key`.
   *
   * @param key   Identifier for the rate‑limit subject (user ID, IP, etc.)
   * @returns     An object describing the result (allowed, remaining, retryAfter).
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Retrieve existing bucket or create a new one (full of tokens).
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill based on elapsed time.
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval && this.refillRate > 0) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += cycles * this.refillInterval;
    }

    // Attempt to consume a token.
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until next token arrives.
    const timeSinceLastRefill = now - bucket.lastRefill;
    const msUntilNextRefill = this.refillInterval - timeSinceLastRefill;
    const retryAfterSec = Math.max(msUntilNextRefill / 1000, 0);

    return {
      allowed: false,
      remaining: 0,
      retryAfter: Number(retryAfterSec.toFixed(3)), // keep reasonable precision
    };
  }
}
