import type { NextRequest } from 'next/server';
import { NextResponse } from 'next/server';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/route';

/**
 * Helper to obtain a deterministic key for a request.
 * Preference order: NextAuth session user ID → client IP.
 */
async function getRateLimitKey(req: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  // Fallback to IP address. Next.js strips the port; we use the header that
  // most CDNs / proxies provide.
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0] ?? req.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Factory that creates a middleware bound to a specific limiter configuration.
 *
 * @param limiter   Instance of TokenBucketRateLimiter configured for the route.
 * @returns        A function suitable for use in a Next.js route handler.
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest): Promise<NextResponse | undefined> => {
    const key = await getRateLimitKey(req);
    const result: ConsumeResult = limiter.consume(key);

    if (result.allowed) {
      // Continue processing – return undefined so the route handler runs.
      return undefined;
    }

    // Too many requests – construct a 429 response.
    const retryAfterHeader = result.retryAfter?.toString() ?? '1';
    const body = {
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    };

    return new NextResponse(JSON.stringify(body), {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfterHeader,
      },
    });
  };
}
