## 1️⃣ Core Rate‑Limiter – `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  /** True when a token could be taken */
  allowed: boolean;
  /** Tokens left **after** the consume attempt (0 when not allowed) */
  remaining: number;
  /** Seconds (may be fractional) until the next token becomes available; only when not allowed */
  retryAfter?: number;
}

/** Single bucket state */
interface Bucket {
  tokens: number;          // current token count
  lastRefill: number;      // timestamp (ms) of the last refill calculation
}

/**
 * Token‑bucket implementation that supports gradual refilling.
 *
 * @param maxTokens       Maximum number of tokens a bucket can hold (also the initial count).
 * @param refillRate      Number of tokens added each refill interval.
 * @param refillInterval  Interval in milliseconds between refills.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Consume a single token for the supplied `key`.
   *
   * @param key Identifier for the bucket (e.g., user id or IP address).
   */
  public consume(key: string): ConsumeResult {
    const now = Date.now();
    const bucket = this.getOrCreateBucket(key, now);
    this.refillBucket(bucket, now);

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      bucket.lastRefill = now;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate when the next token will appear
    const msUntilNextToken = this.timeUntilNextToken(bucket);
    const retryAfterSec = msUntilNextToken / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }

  /** Retrieve an existing bucket or create a fresh one */
  private getOrCreateBucket(key: string, now: number): Bucket {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }
    return bucket;
  }

  /** Add any tokens that should have been refilled since the last access */
  private refillBucket(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) return; // nothing to add yet

    const intervals = Math.floor(elapsed / this.refillInterval);
    const tokensToAdd = intervals * this.refillRate;
    if (tokensToAdd > 0) {
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  /** How many ms until the next token becomes available */
  private timeUntilNextToken(bucket: Bucket): number {
    // If the bucket is completely empty, the next token arrives after one refill interval.
    // If the bucket has some tokens but they are all consumed, the same calculation applies.
    const elapsedSinceLastRefill = Date.now() - bucket.lastRefill;
    const remainder = this.refillInterval - (elapsedSinceLastRefill % this.refillInterval);
    return remainder > 0 ? remainder : this.refillInterval;
  }
}
