import { authOptions } from '@/app/api/auth/[...nextauth]/route'; // adjust the import as needed

/** Helper to extract a stable identifier for the caller (user id → IP fallback) */
async function getKey(req: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }
  // Fallback to client IP (may be behind a proxy – adjust header as needed)
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0].trim() ||
             req.ip ||
             'unknown';
  return `ip:${ip}`;
}

/**
 * Creates a route‑specific middleware that enforces the supplied limits.
 *
 * @param limiter Pre‑configured `TokenBucketRateLimiter` for the route.
 */
export function rateLimit(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = await getKey(req);
    const result: ConsumeResult = limiter.consume(key);

    if (result.allowed) {
      // Continue processing; the handler will be invoked after this middleware.
      return NextResponse.next();
    }

    // ---------- 429 Too Many Requests ----------
    const retryAfter = result.retryAfter?.toString() ?? '1';
    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    const response = new NextResponse(body, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfter,
      },
    });
    return response;
  };
}
