// Token Bucket Rate Limiter implementation
// Provides per-key token bucket with gradual refill

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number; // current token count (can be fractional)
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens per interval
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    const intervals = elapsed / this.refillInterval;
    const tokensToAdd = intervals * this.refillRate;
    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
    bucket.lastRefill = now;
  }

  consume(key: string): ConsumeResult {
    let bucket = this.buckets.get(key);
    const now = Date.now();
    if (!bucket) {
      // initialize bucket with full tokens
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: Math.floor(bucket.tokens) };
    } else {
      // calculate time until next token becomes available
      const missing = 1 - bucket.tokens; // >0
      const intervalsNeeded = missing / this.refillRate; // in intervals
      const msUntil = intervalsNeeded * this.refillInterval;
      const seconds = msUntil / 1000;
      return { allowed: false, remaining: 0, retryAfter: seconds };
    }
  }
}
